(()=>{
const root=document.querySelector('[data-video-id]');if(!root)return;
const trigger=root.querySelector('.au-play'),dialog=document.querySelector('.au-case-dialog');if(!trigger||!dialog)return;
const fullLayer=dialog.querySelector('.au-case-player'),hero=root.querySelector('.au-film'),layer=root.querySelector('.au-background-video'),timing=root.querySelector('.au-timing'),track=root.querySelector('.au-track'),clock=root.querySelector('.au-current'),durationLabel=root.querySelector('.au-duration');
const videos=root.dataset.videos?JSON.parse(root.dataset.videos):[{id:root.dataset.videoId,provider:root.dataset.videoProvider||'vimeo'}];
const reduced=window.__AU_REVIEW_STATIC__===true||matchMedia('(prefers-reduced-motion:reduce)').matches;
let active=0,background=null,currentTime=0,duration=0,heroVisible=true,ratio=16/9,previousOverflow='',generation=0;
const format=value=>Math.floor(value/60).toString().padStart(2,'0')+':'+Math.floor(value%60).toString().padStart(2,'0');
function frame(full){const video=videos[active],iframe=document.createElement('iframe');const url=new URL(video.provider==='youtube'?'https://www.youtube-nocookie.com/embed/'+video.id:'https://player.vimeo.com/video/'+video.id);if(video.provider==='youtube'){Object.entries({autoplay:1,playsinline:1,rel:0}).forEach(([k,v])=>url.searchParams.set(k,v));}else{Object.entries({autoplay:1,muted:full?0:1,controls:full?1:0,loop:full?0:1,playsinline:1,title:0,byline:0,portrait:0,dnt:1}).forEach(([k,v])=>url.searchParams.set(k,v));if(!full)url.searchParams.set('background','1');if(full&&currentTime>0)url.hash='t='+Math.floor(currentTime)+'s';}iframe.src=url.href;iframe.title=root.dataset.projectTitle+(full?' — полный ролик':' — превью');iframe.allow='autoplay; fullscreen; picture-in-picture; encrypted-media';iframe.allowFullscreen=true;if(!full){iframe.tabIndex=-1;iframe.setAttribute('aria-hidden','true');}return iframe;}
function fit(){const iframe=layer?.querySelector('iframe');if(!iframe)return;const width=Math.max(hero.clientWidth,hero.clientHeight*ratio)*1.025;iframe.style.width=width+'px';iframe.style.height=width/ratio+'px';}
function sync(){if(!background)return;const play=heroVisible&&!document.hidden&&!dialog.open&&!reduced;(play?background.play():background.pause()).catch(()=>{});}
function preview(){const token=++generation,previous=background;background=null;layer?.replaceChildren();layer?.classList.remove('is-playing');if(previous)previous.destroy().catch(()=>{});currentTime=duration=0;ratio=16/9;if(clock)clock.textContent='00:00';if(durationLabel)durationLabel.textContent='—:—';if(track)track.style.setProperty('--video-progress','0%');if(timing)timing.hidden=videos[active].provider!=='vimeo';root.querySelectorAll('[data-video-index]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.videoIndex)===active)));if(reduced||videos[active].provider!=='vimeo'||!window.Vimeo||!layer)return;const iframe=frame(false);layer.append(iframe);fit();const player=new Vimeo.Player(iframe);background=player;player.on('playing',()=>{if(token!==generation)return;layer.classList.add('is-playing');root.dataset.videoState='playing';if(!heroVisible||document.hidden||dialog.open)player.pause().catch(()=>{});});player.on('timeupdate',event=>{if(token!==generation)return;currentTime=event.seconds;duration=event.duration;if(clock)clock.textContent=format(currentTime);if(durationLabel)durationLabel.textContent=format(duration);if(track)track.style.setProperty('--video-progress',(duration?currentTime/duration*100:0)+'%');if(timing)timing.setAttribute('aria-label',format(currentTime)+' из '+format(duration));});player.on('error',()=>{if(token===generation){layer.classList.remove('is-playing');root.dataset.videoState='poster';}});player.ready().then(async()=>{const dimensions=await Promise.all([player.getVideoWidth(),player.getVideoHeight(),player.getDuration()]);if(token!==generation)return;ratio=dimensions[0]/dimensions[1];duration=dimensions[2];if(durationLabel)durationLabel.textContent=format(duration);fit();sync();}).catch(()=>{if(token===generation)root.dataset.videoState='poster';});}
new ResizeObserver(fit).observe(hero);new IntersectionObserver(es=>{heroVisible=es[0].isIntersecting;sync();},{threshold:.05}).observe(hero);document.addEventListener('visibilitychange',sync);
root.querySelectorAll('[data-video-index]').forEach(b=>b.addEventListener('click',()=>{active=Number(b.dataset.videoIndex);preview();}));
trigger.addEventListener('click',()=>{if(dialog.open)return;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';fullLayer.replaceChildren(frame(true));let source=dialog.querySelector('.au-case-video-source');if(!source){source=document.createElement('a');source.className='au-case-video-source';source.target='_blank';source.rel='noopener';dialog.append(source);}const video=videos[active];source.href=video.provider==='youtube'?'https://www.youtube.com/watch?v='+video.id:'https://vimeo.com/'+video.id;source.textContent='Открыть на '+(video.provider==='youtube'?'YouTube':'Vimeo');dialog.showModal();sync();});
dialog.querySelector('.au-case-dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const b=dialog.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)dialog.close();});dialog.addEventListener('close',()=>{fullLayer.replaceChildren();document.body.style.overflow=previousOverflow;trigger.focus({preventScroll:true});sync();});preview();
})();
